#!/usr/bin/env Rscript

# ===============================================================================
# process_stats_summary.R
#
# Originally created by:
#     - Samuel Ruiz-Pérez <samper@cancer.dk>
#     https://github.com/grothlab/crepas/
#
# Description:
#     Script to process the samtools_stats_summary table generated by the
#     grothlab/crepas pipeline. Cleans and reshapes the summary table, calculates
#     additional statistics (e.g., reads removed between filtering steps), and outputs a processed
#     summary table for downstream analysis and visualization.
# ===============================================================================

options(show.error.locations = TRUE)

required.libs <- c("dplyr", "readr", "tidyr", "ggplot2", "forcats", "argparse")

suppressPackageStartupMessages({
  lapply(required.libs, FUN = function(x) {
    do.call("library", list(x))
  })
})


parser <- ArgumentParser()


parser$add_argument("-s","--summary_table", action = "store",
                    type = "character",
                    help = "Summary table from samtools_stats_summary [required]")

parser$add_argument("-g","--endogenous_genome_name", action = "store",
                    type = "character",
                    default = "GRCh38",
                    help = "Name of the endogenous genome [required]")

parser$add_argument("-e","--exogenous_genome_name", action = "store",
                    type = "character",
                    help = "Name of the exogenous (spike-in) genome if applicable [optional]")

parser$add_argument("-n", "--prefix", action = "store",
                    default = "final_samtools_stats_summary",
                    type = "character",
                    help = "Prefix for output files and plot title")

parser$add_argument("-o", "--outdir", action = "store",
                    default = "./",
                    type = "character",
                    help = "Path to output directory for processed tables and plots")

opt <- parser$parse_args()

if (is.null(opt$summary_table)) {
  stop("The summary table is required.")
} else if (!file.exists(opt$summary_table)) {
  stop("The summary table file does not exist.")
}

if (is.null(opt$endogenous_genome_name) || !nzchar(opt$endogenous_genome_name)) {
  stop("The endogenous genome name is required.")
}

# Treat an empty exogenous genome name as no spike-in
if (!is.null(opt$exogenous_genome_name) && !nzchar(opt$exogenous_genome_name)) {
  opt$exogenous_genome_name <- NULL
}

# Name for the column holding the difference between two processing steps,
# built from the full names of the two columns it is derived from.
difference_colname <- function(minuend, subtrahend) {
  paste0(minuend, "_minus_", subtrahend)
}

summary_table <- read_tsv(opt$summary_table, col_names = TRUE)

if (is.null(opt$exogenous_genome_name)) {

  tmp <- summary_table %>%
                  # In the column names replace any space or dash with underscore
                  rename_with(~ gsub("[- ]", "_", .x)) %>%
                  # Remove any row before library merging (containing ".Lb.")
                  filter(!grepl("\\.Lb\\.", ID)) %>%
                  # remove ".sorted" and ".sorted.bam" from the ID column
                  mutate(
                    ID = gsub("\\.sorted\\.bam$", "", ID),
                    ID = gsub("\\.sorted$", "", ID),
                    # The following is to avoid endo and exogenous files merging together
                    # ID = gsub("\\.flT2$", "_flT2", ID),
                    # ID = gsub("\\.allo$", "_allo", ID),
                    # ID = gsub("\\.flT3$", "_flT3", ID),
                    # ID = gsub("\\..shifted$", "_shifted", ID),
                    # ID = gsub("\\.dSp$", "_dSp", ID),
                    # Merge "rmO" with the preceding step so the two
                    # branches don't collapse onto the same processing_step
                    ID = gsub("\\.([^.]+)\\.([^.]*rmO)$", ".\\1_\\2", ID),
                    # split ID by ".", processing_step is the last element
                    processing_step = gsub(".*\\.", "", ID),
                    processing_step = fct_relevel(processing_step, rev(unique(processing_step))),
                    sample = sub("\\.mLb.*$", "", ID)) %>%
                  select(-ID) %>%
                  # First, pivot the data to long format for easier reshaping
                  pivot_longer(
                    cols = -c(sample, processing_step),
                    names_to = "stat",
                    values_to = "value"
                  ) %>%
                  # sort by processing_step factor levels
                  arrange(processing_step) %>%
                  # Create new column names by combining processing_step and stat
                  mutate(stat = paste(processing_step, stat, sep = "_")) %>%
                  select(-processing_step) %>%
                  # Pivot back to wide format
                  pivot_wider(
                    names_from = stat,
                    values_from = value
                  )

  # If there is flT3_raw_total_sequences column, use it to calculate the reads
  # removed between flT1 and flT3 (multimappers AND low quality alignments)
  if ("flT3_raw_total_sequences" %in% colnames(tmp) &&
      "flT1_raw_total_sequences" %in% colnames(tmp)) {
    diff_colname <- difference_colname("flT1_raw_total_sequences", "flT3_raw_total_sequences")
    tmp <- tmp %>%
          mutate(
            # Add a new column for the reads removed between the two steps
            !!sym(diff_colname) := flT1_raw_total_sequences - flT3_raw_total_sequences) %>%
          # move the difference column after last column with flT1 in the name
          relocate(!!sym(diff_colname), .after = tail(grep("flT1", colnames(.[-which(colnames(.) == diff_colname)])), n = 1))
  }

} else {

  tmp <- summary_table %>%
                  # In the column names replace any space or dash with underscore
                  rename_with(~ gsub("[- ]", "_", .x)) %>%
                  # Remove any row before library merging (containing ".Lb.")
                  filter(!grepl("\\.Lb\\.", ID)) %>%
                  # remove ".sorted" and ".sorted.bam" from the ID column
                  mutate(
                    ID = gsub("\\.sorted\\.bam$", "", ID),
                    ID = gsub("\\.sorted$", "", ID),
                    # The following is to avoid endo and exogenous files merging together
                    ID = ifelse(grepl(paste0("\\.", opt$endogenous_genome_name, "\\."), ID),
                                gsub("\\.flT2$", paste0(".", opt$endogenous_genome_name, "_flT2"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                                gsub("\\.flT2$", paste0(".", opt$exogenous_genome_name, "_flT2"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$endogenous_genome_name, "\\."), ID),
                                gsub("\\.allo$", paste0(".", opt$endogenous_genome_name, "_allo"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                                gsub("\\.allo$", paste0(".", opt$exogenous_genome_name, "_allo"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$endogenous_genome_name, "\\."), ID),
                                gsub("\\..shifted$", paste0(".", opt$endogenous_genome_name, "_shifted"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                                gsub("\\..shifted$", paste0(".", opt$exogenous_genome_name, "_shifted"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$endogenous_genome_name, "\\."), ID),
                                gsub("\\.flT3$", paste0(".", opt$endogenous_genome_name, "_flT3"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                                gsub("\\.flT3$", paste0(".", opt$exogenous_genome_name, "_flT3"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                                gsub("\\.flTbl$", paste0(".", opt$exogenous_genome_name, "_flTbl"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                                gsub("\\.rmO$", paste0(".", opt$exogenous_genome_name, "_rmO"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$endogenous_genome_name, "\\."), ID),
                          gsub("\\.dSp(.*)$", paste0(".", opt$endogenous_genome_name, "_dSp\\1"), ID), ID),
                    ID = ifelse(grepl(paste0("\\.", opt$exogenous_genome_name, "\\."), ID),
                          gsub("\\.dSp(.*)$", paste0(".", opt$exogenous_genome_name, "_dSp\\1"), ID), ID),
                    # "rmO" (remove-orphans) can follow either flT3 directly
                    # (TE-counting branch) or flTbl (blacklist-filtered
                    # branch); merge it with the preceding step so the two
                    # branches don't collapse onto the same processing_step
                    ID = gsub("\\.([^.]+)\\.([^.]*rmO)$", ".\\1_\\2", ID),
                    # split ID by ".", processing_step is the last element
                    processing_step = gsub(".*\\.", "", ID),
                    processing_step = fct_relevel(processing_step, rev(unique(processing_step))),
                    sample = sub("\\.mLb.*$", "", ID)) %>%
                    dplyr::select(-ID) %>%
                    # First, pivot the data to long format for easier reshaping
                    pivot_longer(
                      cols = -c(sample, processing_step),
                      names_to = "stat",
                      values_to = "value"
                    ) %>%
                    # sort by processing_step factor levels
                    arrange(processing_step) %>%
                    # Create new column names by combining processing_step and stat
                    mutate(stat = paste(processing_step, stat, sep = "_")) %>%
                    dplyr::select(-processing_step) %>%
                    # Pivot back to wide format
                    pivot_wider(
                      names_from = stat,
                      values_from = value
                    )

  actual_flt2_rts_colname <- paste0(opt$endogenous_genome_name, "_flT2_raw_total_sequences")
  actual_flt3_rts_colname <- paste0(opt$endogenous_genome_name, "_flT3_raw_total_sequences")

  # If there is an endogenous flT3_raw_total_sequences column, use it to calculate
  # the reads removed between the two steps
  if (actual_flt3_rts_colname %in% colnames(tmp)) {

    # add the difference column, against flT2 if present and otherwise against flT1
    if (actual_flt2_rts_colname %in% colnames(tmp)) {
      diff_colname <- difference_colname(actual_flt2_rts_colname, actual_flt3_rts_colname)
      tmp <- tmp %>%
        mutate(!!sym(diff_colname) := !!sym(actual_flt2_rts_colname) - !!sym(actual_flt3_rts_colname)) %>%
        # move the difference column after last column with flT2 in the name
        relocate(!!sym(diff_colname), .after = tail(grep("flT2", colnames(.[-which(colnames(.) == diff_colname)])), n = 1))
    } else if ("flT1_raw_total_sequences" %in% colnames(tmp)) {
      diff_colname <- difference_colname("flT1_raw_total_sequences", actual_flt3_rts_colname)
      tmp <- tmp %>%
        mutate(!!sym(diff_colname) := flT1_raw_total_sequences - !!sym(actual_flt3_rts_colname)) %>%
        # move the difference column after last column with flT1 in the name
        relocate(!!sym(diff_colname), .after = tail(grep("flT1", colnames(.[-which(colnames(.) == diff_colname)])), n = 1))
    } else {
      warning("No valid flT1 or flT2 columns found to compute the difference against flT3.")
      stop("Processing cannot continue without valid columns.")
    }
  }
}

# write the processed table with all the columns to a file
write_tsv(tmp, file.path(opt$outdir, paste0(opt$prefix, ".all.tsv")))

# Also write a reduced table with only the read-count columns
totals <- tmp %>%
  dplyr::select(sample, matches("_raw_total_sequences$|_minus_"))

write_tsv(totals, file.path(opt$outdir, paste0(opt$prefix, ".totals.tsv")))

cat("Processing completed on", format(Sys.time()), "\n")
